"""Kitchen Sink: a WizardForm (the Dialogs page shows it): its pages were edited in the
designer (Previous Page / Next Page), ValidatePage keeps a page until it is filled in,
NextPage skips a page, Finish collects the answers."""

from vp6 import *


class frmWizard(WizardForm):
    # region VP6 Designer - generated by the form designer, do not edit
    def InitializeComponent(self):
        self.Caption = 'Kitchen Sink setup'
        self.Width = 520
        self.Height = 400
        self.Pages = ['Welcome|This wizard is a WizardForm', 'Your name|Next checks that you typed one (ValidatePage)', "Your color|NextPage skips this page if you're Zed", 'Done|Finish, and the Dialogs page shows your answers']
        self.lblWelcome = Label(self, Page=0,
                                Caption="Each page is one of the form's Pages; its controls were drawn on it in the designer. Click Next.",
                                Left=16, Top=16, Width=440, Height=60, WordWrap=True, TabIndex=1)
        self.txtName = TextBox(self, Page=1, Text='', Left=16, Top=16, Width=240, Height=25,
                               TabIndex=2)
        self.optColor = ControlArray()
        self.optColor[0] = OptionButton(self, Page=2, Caption='Red', Left=16, Top=16, Width=140,
                                        Height=25, Value=True, TabIndex=3)
        self.optColor[1] = OptionButton(self, Page=2, Caption='Green', Left=16, Top=44, Width=140,
                                        Height=25, TabIndex=4)
        self.optColor[2] = OptionButton(self, Page=2, Caption='Blue', Left=16, Top=72, Width=140,
                                        Height=25, TabIndex=5)
        self.lblSummary = Label(self, Page=3, Caption='', Left=16, Top=16, Width=440, Height=60,
                                WordWrap=True, TabIndex=6)
    # endregion

    answers = None  # (name, color) once finished

    def chosen_color(self):
        return next((option.Caption for option in self.optColor if option.Value), "?")

    def Form_ValidatePage(self, Page):
        if Page == 1 and not self.txtName.Text.strip():
            MsgBox("Please type your name", vpExclamation, "Kitchen Sink setup")
            return True  # (stays on the page)

    def Form_NextPage(self, Page):
        if Page == 1 and self.txtName.Text.strip() == "Zed":
            return 3  # (Zed's color is known: straight to the last page)

    def Form_PageChange(self):
        if self.CurrentPage == 3:
            self.lblSummary.Caption = f"Hello {self.txtName.Text.strip()}: you chose " \
                                      f"{self.chosen_color()}."

    def Form_Finish(self):
        self.answers = (self.txtName.Text.strip(), self.chosen_color())

    def Form_Cancel(self):
        return MsgBox("Leave the wizard?", vpYesNo + vpQuestion) != vpYes  # (True: stays)


if __name__ == "__main__":
    run(frmWizard)
